// Undo/Redo
undoBtn.addEventListener('click', undo);
redoBtn.addEventListener('click', redo);

// Keyboard shortcuts
document.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'z' && !e.shiftKey) {
        e.preventDefault();
        undo();
    } else if ((e.ctrlKey || e.metaKey) && (e.key === 'y' || (e.key === 'z' && e.shiftKey))) {
        e.preventDefault();
        redo();
    }
});

// Drawing functions
function startDrawing(e) {
    if (currentTool === 'fill') {
        const coords = getCanvasCoordinates(e);
        saveState();
        floodFill(coords.x, coords.y, currentColor);
        return;
    }
    
    isDrawing = true;
    saveState();
    const coords = getCanvasCoordinates(e);
    lastX = coords.x;
    lastY = coords.y;
}

function draw(e) {
    if (!isDrawing || currentTool === 'fill') return;
    
    const coords = getCanvasCoordinates(e);
    const currentX = coords.x;
    const currentY = coords.y;
    
    ctx.beginPath();
    ctx.moveTo(lastX, lastY);
    ctx.lineTo(currentX, currentY);
    ctx.stroke();
    
    lastX = currentX;
    lastY = currentY;
}

function stopDrawing() {
    if (isDrawing) {
        isDrawing = false;
    }
}

// Touch events for mobile
function startDrawingTouch(e) {
    e.preventDefault();
    if (currentTool === 'fill') {
        const coords = getCanvasCoordinates(e);
        saveState();
        floodFill(coords.x, coords.y, currentColor);
        return;
    }
    
    isDrawing = true;
    saveState();
    const coords = getCanvasCoordinates(e);
    lastX = coords.x;
    lastY = coords.y;
}

function drawTouch(e) {
    e.preventDefault();
    if (!isDrawing || currentTool === 'fill') return;
    
    const coords = getCanvasCoordinates(e);
    const currentX = coords.x;
    const currentY = coords.y;
    
    ctx.beginPath();
    ctx.moveTo(lastX, lastY);
    ctx.lineTo(currentX, currentY);
    ctx.stroke();
    
    lastX = currentX;
    lastY = currentY;
}

function stopDrawingTouch(e) {
    e.preventDefault();
    isDrawing = false;
}

// Event listeners
canvas.addEventListener('mousedown', startDrawing);
canvas.addEventListener('mousemove', draw);
canvas.addEventListener('mouseup', stopDrawing);
canvas.addEventListener('mouseout', stopDrawing);

canvas.addEventListener('touchstart', startDrawingTouch);
canvas.addEventListener('touchmove', drawTouch);
canvas.addEventListener('touchend', stopDrawingTouch);

// Clear canvas
clearBtn.addEventListener('click', () => {
    if (confirm('Clear the entire canvas?')) {
        saveState();
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        // Redraw the image if one was selected
        if (currentImage) {
            loadImageToCanvas(currentImage, false);
        }
    }
});

// Helper function to load image to canvas
function loadImageToCanvas(picture, shouldSaveState = true) {
    // #region agent log
    fetch('http://127.0.0.1:7242/ingest/3400234f-86bf-4b16-8be0-11dc36af9821',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'script.js:508',message:'loadImageToCanvas called',data:{imageName:picture.name,urlStart:picture.url.substring(0,50),isDataUrl:picture.url.startsWith('data:'),shouldSaveState},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'F'})}).catch(()=>{});
    // #endregion
    if (shouldSaveState) {
        saveState();
    }
    
    const img = new Image();
    img.crossOrigin = 'anonymous'; // Not needed for data URLs but harmless
    img.onload = function() {
        // #region agent log
        fetch('http://127.0.0.1:7242/ingest/3400234f-86bf-4b16-8be0-11dc36af9821',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'script.js:517',message:'Image loaded in loadImageToCanvas',data:{imageName:picture.name,imgComplete:img.complete,imgNaturalWidth:img.naturalWidth},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'F'})}).catch(()=>{});
        // #endregion
        const imgAspect = img.width / img.height;
        const canvasAspect = canvas.width / canvas.height;
        let drawWidth, drawHeight, offsetX = 0, offsetY = 0;
        if (imgAspect > canvasAspect) {
            drawWidth = canvas.width * 0.9;
            drawHeight = drawWidth / imgAspect;
            offsetY = (canvas.height - drawHeight) / 2;
            offsetX = (canvas.width - drawWidth) / 2;
        } else {
            drawHeight = canvas.height * 0.9;
            drawWidth = drawHeight * imgAspect;
            offsetX = (canvas.width - drawWidth) / 2;
            offsetY = (canvas.height - drawHeight) / 2;
        }
        ctx.drawImage(img, offsetX, offsetY, drawWidth, drawHeight);
        updateUndoRedoButtons();
    };
    
    img.onerror = function() {
        // #region agent log
        fetch('http://127.0.0.1:7242/ingest/3400234f-86bf-4b16-8be0-11dc36af9821',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'script.js:533',message:'Image load error (duplicate function?)',data:{imageName:picture.name,url:picture.url.substring(0,100)},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'D'})}).catch(()=>{});
        // #endregion
        console.error('Failed to load image:', picture.name, picture.url);
        alert('Failed to load image. Please check that the image file exists.');
    };
    
    // #region agent log
    fetch('http://127.0.0.1:7242/ingest/3400234f-86bf-4b16-8be0-11dc36af9821',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'script.js:538',message:'Setting img.src (duplicate function?)',data:{imageName:picture.name,urlStart:picture.url.substring(0,50),isDataUrl:picture.url.startsWith('data:')},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'D'})}).catch(()=>{});
    // #endregion
    img.src = picture.url;
}

// Save drawing
saveBtn.addEventListener('click', () => {
    try {
        const dataUrl = canvas.toDataURL('image/png');
        const link = document.createElement('a');
        link.download = currentImage ? currentImage.name.replace(/[^a-z0-9]/gi, '_') + '_colored.png' : 'pastel-painting.png';
        link.href = dataUrl;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    } catch (e) {
        console.error('Error saving image:', e);
        alert('Error saving image. Please try again.');
    }
});

// Drawing functions for coloring book pictures
function drawButterfly(ctx, size) {
    const centerX = size / 2;
    const centerY = size / 2;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    
    // Body
    ctx.beginPath();
    ctx.ellipse(centerX, centerY, 8, 40, 0, 0, Math.PI * 2);
    ctx.stroke();
    
    // Top wings
    ctx.beginPath();
    ctx.ellipse(centerX - 30, centerY - 20, 35, 25, -0.3, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(centerX + 30, centerY - 20, 35, 25, 0.3, 0, Math.PI * 2);
    ctx.stroke();
    
    // Bottom wings
    ctx.beginPath();
    ctx.ellipse(centerX - 25, centerY + 15, 30, 20, 0.3, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(centerX + 25, centerY + 15, 30, 20, -0.3, 0, Math.PI * 2);
    ctx.stroke();
    
    // Antennae
    ctx.beginPath();
    ctx.moveTo(centerX - 5, centerY - 40);
    ctx.lineTo(centerX - 15, centerY - 50);
    ctx.moveTo(centerX + 5, centerY - 40);
    ctx.lineTo(centerX + 15, centerY - 50);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(centerX - 15, centerY - 50, 3, 0, Math.PI * 2);
    ctx.arc(centerX + 15, centerY - 50, 3, 0, Math.PI * 2);
    ctx.stroke();
}

function drawFlower(ctx, size) {
    const centerX = size / 2;
    const centerY = size / 2;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    
    // Petals
    for (let i = 0; i < 8; i++) {
        const angle = (Math.PI * 2 * i) / 8;
        const x = centerX + Math.cos(angle) * 40;
        const y = centerY + Math.sin(angle) * 40;
        ctx.beginPath();
        ctx.arc(x, y, 20, 0, Math.PI * 2);
        ctx.stroke();
    }
    
    // Center
    ctx.beginPath();
    ctx.arc(centerX, centerY, 15, 0, Math.PI * 2);
    ctx.stroke();
    
    // Stem
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + 40);
    ctx.lineTo(centerX, size - 20);
    ctx.stroke();
    
    // Leaves
    ctx.beginPath();
    ctx.ellipse(centerX - 15, size - 30, 12, 8, -0.5, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(centerX + 15, size - 25, 12, 8, 0.5, 0, Math.PI * 2);
    ctx.stroke();
}

function drawHeart(ctx, size) {
    const centerX = size / 2;
    const centerY = size / 2;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + 20);
    ctx.bezierCurveTo(centerX, centerY + 10, centerX - 30, centerY - 20, centerX - 30, centerY - 10);
    ctx.bezierCurveTo(centerX - 30, centerY, centerX - 15, centerY + 5, centerX, centerY + 20);
    ctx.bezierCurveTo(centerX + 15, centerY + 5, centerX + 30, centerY, centerX + 30, centerY - 10);
    ctx.bezierCurveTo(centerX + 30, centerY - 20, centerX, centerY + 10, centerX, centerY + 20);
    ctx.stroke();
}

function drawStar(ctx, size) {
    const centerX = size / 2;
    const centerY = size / 2;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    
    const spikes = 5;
    const outerRadius = 50;
    const innerRadius = 25;
    
    ctx.beginPath();
    for (let i = 0; i < spikes * 2; i++) {
        const radius = i % 2 === 0 ? outerRadius : innerRadius;
        const angle = (Math.PI * i) / spikes - Math.PI / 2;
        const x = centerX + Math.cos(angle) * radius;
        const y = centerY + Math.sin(angle) * radius;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.stroke();
}

function drawCat(ctx, size) {
    const centerX = size / 2;
    const centerY = size / 2;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    
    // Head
    ctx.beginPath();
    ctx.arc(centerX, centerY - 20, 40, 0, Math.PI * 2);
    ctx.stroke();
    
    // Ears
    ctx.beginPath();
    ctx.moveTo(centerX - 25, centerY - 50);
    ctx.lineTo(centerX - 15, centerY - 70);
    ctx.lineTo(centerX - 5, centerY - 55);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(centerX + 25, centerY - 50);
    ctx.lineTo(centerX + 15, centerY - 70);
    ctx.lineTo(centerX + 5, centerY - 55);
    ctx.stroke();
    
    // Eyes
    ctx.beginPath();
    ctx.arc(centerX - 15, centerY - 25, 8, 0, Math.PI * 2);
    ctx.arc(centerX + 15, centerY - 25, 8, 0, Math.PI * 2);
    ctx.stroke();
    
    // Nose
    ctx.beginPath();
    ctx.moveTo(centerX, centerY - 10);
    ctx.lineTo(centerX - 8, centerY + 5);
    ctx.lineTo(centerX + 8, centerY + 5);
    ctx.closePath();
    ctx.stroke();
    
    // Mouth
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + 5);
    ctx.lineTo(centerX - 10, centerY + 15);
    ctx.moveTo(centerX, centerY + 5);
    ctx.lineTo(centerX + 10, centerY + 15);
    ctx.stroke();
    
    // Body
    ctx.beginPath();
    ctx.ellipse(centerX, centerY + 50, 35, 50, 0, 0, Math.PI * 2);
    ctx.stroke();
}

function drawRainbow(ctx, size) {
    const centerX = size / 2;
    const centerY = size / 2 + 30;
    ctx.lineWidth = 4;
    
    const colors = ['#FFB3D9', '#FFD9B3', '#FFF0B3', '#C5E1A5', '#B3E5FC', '#E1BEE7'];
    const radius = 60;
    
    for (let i = 0; i < colors.length; i++) {
        ctx.strokeStyle = colors[i];
        ctx.beginPath();
        ctx.arc(centerX, centerY, radius - (i * 8), 0, Math.PI);
        ctx.stroke();
    }
    
    // Clouds
    ctx.strokeStyle = '#5D6D7E';
    ctx.lineWidth = 3;
    drawCloud(ctx, centerX - 80, centerY - 10, 25);
    drawCloud(ctx, centerX + 80, centerY - 10, 25);
}

function drawSun(ctx, size) {
    const centerX = size / 2;
    const centerY = size / 2;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    
    // Center circle
    ctx.beginPath();
    ctx.arc(centerX, centerY, 30, 0, Math.PI * 2);
    ctx.stroke();
    
    // Rays
    for (let i = 0; i < 12; i++) {
        const angle = (Math.PI * 2 * i) / 12;
        ctx.beginPath();
        ctx.moveTo(centerX + Math.cos(angle) * 30, centerY + Math.sin(angle) * 30);
        ctx.lineTo(centerX + Math.cos(angle) * 50, centerY + Math.sin(angle) * 50);
        ctx.stroke();
    }
}

function drawTree(ctx, size) {
    const centerX = size / 2;
    const bottomY = size - 30;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    
    // Trunk
    ctx.beginPath();
    ctx.rect(centerX - 15, bottomY - 80, 30, 80);
    ctx.stroke();
    
    // Leaves (circles)
    ctx.beginPath();
    ctx.arc(centerX, bottomY - 100, 40, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(centerX - 25, bottomY - 120, 30, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(centerX + 25, bottomY - 120, 30, 0, Math.PI * 2);
    ctx.stroke();
}

function drawHouse(ctx, size) {
    const centerX = size / 2;
    const bottomY = size - 30;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    
    // Base
    ctx.beginPath();
    ctx.rect(centerX - 50, bottomY - 80, 100, 80);
    ctx.stroke();
    
    // Roof
    ctx.beginPath();
    ctx.moveTo(centerX - 60, bottomY - 80);
    ctx.lineTo(centerX, bottomY - 130);
    ctx.lineTo(centerX + 60, bottomY - 80);
    ctx.closePath();
    ctx.stroke();
    
    // Door
    ctx.beginPath();
    ctx.rect(centerX - 15, bottomY - 50, 30, 50);
    ctx.stroke();
    
    // Window
    ctx.beginPath();
    ctx.rect(centerX - 35, bottomY - 60, 20, 20);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(centerX - 25, bottomY - 60);
    ctx.lineTo(centerX - 25, bottomY - 40);
    ctx.moveTo(centerX - 35, bottomY - 50);
    ctx.lineTo(centerX - 15, bottomY - 50);
    ctx.stroke();
}

function drawCloud(ctx, x, y, size) {
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.arc(x + size * 0.8, y, size * 0.9, 0, Math.PI * 2);
    ctx.arc(x + size * 1.6, y, size, 0, Math.PI * 2);
    ctx.arc(x + size * 0.4, y - size * 0.6, size * 0.7, 0, Math.PI * 2);
    ctx.arc(x + size * 1.2, y - size * 0.6, size * 0.7, 0, Math.PI * 2);
    ctx.stroke();
}

function drawMoon(ctx, size) {
    const centerX = size / 2;
    const centerY = size / 2;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    
    ctx.beginPath();
    ctx.arc(centerX, centerY, 40, 0, Math.PI * 2);
    ctx.stroke();
    
    // Crescent
    ctx.beginPath();
    ctx.arc(centerX + 15, centerY, 35, 0, Math.PI * 2);
    ctx.fillStyle = '#FFFFFF';
    ctx.fill();
    ctx.stroke();
    
    // Stars
    for (let i = 0; i < 5; i++) {
        const angle = (Math.PI * 2 * i) / 5;
        const x = centerX + Math.cos(angle) * 60;
        const y = centerY + Math.sin(angle) * 60;
        drawSmallStar(ctx, x, y, 8);
    }
}

function drawFish(ctx, size) {
    const centerX = size / 2;
    const centerY = size / 2;
    ctx.lineWidth = 3;
    ctx.strokeStyle = '#5D6D7E';
    
    // Body
    ctx.beginPath();
    ctx.ellipse(centerX, centerY, 50, 30, 0, 0, Math.PI * 2);
    ctx.stroke();
    
    // Tail
    ctx.beginPath();
    ctx.moveTo(centerX - 50, centerY);
    ctx.lineTo(centerX - 70, centerY - 20);
    ctx.lineTo(centerX - 70, centerY + 20);
    ctx.closePath();
    ctx.stroke();
    
    // Eye
    ctx.beginPath();
    ctx.arc(centerX + 20, centerY - 10, 8, 0, Math.PI * 2);
    ctx.stroke();
    
    // Fins
    ctx.beginPath();
    ctx.moveTo(centerX + 10, centerY - 30);
    ctx.lineTo(centerX + 30, centerY - 35);
    ctx.lineTo(centerX + 20, centerY - 20);
    ctx.closePath();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(centerX + 10, centerY + 30);
    ctx.lineTo(centerX + 30, centerY + 35);
    ctx.lineTo(centerX + 20, centerY + 20);
    ctx.closePath();
    ctx.stroke();
}

// Helper function to draw small star
function drawSmallStar(ctx, x, y, radius) {
    const spikes = 5;
    ctx.beginPath();
    for (let i = 0; i < spikes * 2; i++) {
        const r = i % 2 === 0 ? radius : radius / 2;
        const angle = (Math.PI * i) / spikes - Math.PI / 2;
        const px = x + Math.cos(angle) * r;
        const py = y + Math.sin(angle) * r;
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.stroke();
}

// Initialize gallery
function initGallery() {
    galleryGrid.innerHTML = '';
    coloringPictures.forEach((picture) => {
        const item = document.createElement('div');
        item.className = 'gallery-item';
        
        // Create loading indicator
        const loadingDiv = document.createElement('div');
        loadingDiv.className = 'gallery-loading';
        loadingDiv.textContent = 'Loading...';
        
        // Create img element
        const img = document.createElement('img');
        img.crossOrigin = 'anonymous'; // Prevent CORS issues
        img.alt = picture.name;
        img.style.width = '100%';
        img.style.height = '100%';
        img.style.objectFit = 'contain';
        img.style.background = '#FFFFFF';
        img.style.padding = '10px';
        img.style.display = 'none';
        
        // Try loading image with CORS proxy
        img.onload = function() {
            img.style.display = 'block';
            if (loadingDiv.parentElement) {
                loadingDiv.remove();
            }
        };
        
        img.onerror = function() {
            loadingDiv.textContent = 'Image not available';
            loadingDiv.style.color = '#ff6b6b';
        };
        
        // Load local image
        // #region agent log
        fetch('http://127.0.0.1:7242/ingest/3400234f-86bf-4b16-8be0-11dc36af9821',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'script.js:951',message:'Setting img.src in initGallery',data:{imageName:picture.name,urlStart:picture.url.substring(0,50),isDataUrl:picture.url.startsWith('data:')},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'E'})}).catch(()=>{});
        // #endregion
        img.src = picture.url;
        
        const label = document.createElement('div');
        label.className = 'gallery-item-label';
        label.textContent = picture.name;
        
        item.appendChild(loadingDiv);
        item.appendChild(img);
        item.appendChild(label);
        item.addEventListener('click', () => selectPicture(picture));
        
        galleryGrid.appendChild(item);
    });
}

// Select picture to color
function selectPicture(picture) {
    // Fill canvas with white
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    
    // Show loading message
    const loadingMsg = document.createElement('div');
    loadingMsg.style.position = 'absolute';
    loadingMsg.style.top = '50%';
    loadingMsg.style.left = '50%';
    loadingMsg.style.transform = 'translate(-50%, -50%)';
    loadingMsg.style.background = 'rgba(255, 255, 255, 0.9)';
    loadingMsg.style.padding = '15px 25px';
    loadingMsg.style.borderRadius = '10px';
    loadingMsg.style.boxShadow = '0 4px 12px rgba(0,0,0,0.15)';
    loadingMsg.style.zIndex = '100';
    loadingMsg.textContent = 'Loading picture...';
    loadingMsg.style.fontWeight = '600';
    loadingMsg.style.color = 'var(--text)';
    canvas.parentElement.style.position = 'relative';
    canvas.parentElement.appendChild(loadingMsg);
    
    // Function to draw image on canvas
    function drawImageOnCanvas(img) {
        // Remove loading message
        if (loadingMsg.parentElement) {
            loadingMsg.remove();
        }
        
        // Calculate dimensions to fit canvas while maintaining aspect ratio
        const imgAspect = img.width / img.height;
        const canvasAspect = canvas.width / canvas.height;
        
        let drawWidth, drawHeight, offsetX = 0, offsetY = 0;
        
        if (imgAspect > canvasAspect) {
            // Image is wider
            drawWidth = canvas.width * 0.9;
            drawHeight = drawWidth / imgAspect;
            offsetY = (canvas.height - drawHeight) / 2;
            offsetX = (canvas.width - drawWidth) / 2;
        } else {
            // Image is taller
            drawHeight = canvas.height * 0.9;
            drawWidth = drawHeight * imgAspect;
            offsetX = (canvas.width - drawWidth) / 2;
            offsetY = (canvas.height - drawHeight) / 2;
        }
        
        // Draw the image on canvas
        ctx.drawImage(img, offsetX, offsetY, drawWidth, drawHeight);
        currentImage = picture;
        
        // Reset undo/redo stacks when new image is loaded
        undoStack = [];
        redoStack = [];
        
        // Save the initial state of the loaded image
        saveState();
        updateUndoRedoButtons();
    }
    
    // Load image directly from data URL (embedded in code - no server needed!)
    // Since images are now base64 data URLs, they won't taint the canvas
    const img = new Image();
    // #region agent log
    fetch('http://127.0.0.1:7242/ingest/3400234f-86bf-4b16-8be0-11dc36af9821',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'script.js:1031',message:'Creating Image object for selectPicture',data:{imageName:picture.name,urlStart:picture.url.substring(0,50),isDataUrl:picture.url.startsWith('data:')},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'A'})}).catch(()=>{});
    // #endregion
    img.crossOrigin = 'anonymous'; // Not needed for data URLs but harmless
    img.onload = function() {
        // #region agent log
        fetch('http://127.0.0.1:7242/ingest/3400234f-86bf-4b16-8be0-11dc36af9821',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'script.js:1035',message:'Image loaded in selectPicture',data:{imageName:picture.name,urlType:picture.url.substring(0,30),imgComplete:img.complete,imgNaturalWidth:img.naturalWidth},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'A'})}).catch(()=>{});
        // #endregion
        drawImageOnCanvas(img);
    };
    img.onerror = function() {
        // #region agent log
        fetch('http://127.0.0.1:7242/ingest/3400234f-86bf-4b16-8be0-11dc36af9821',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'script.js:1042',message:'Image load error in selectPicture',data:{imageName:picture.name,url:picture.url.substring(0,100)},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'A'})}).catch(()=>{});
        // #endregion
        console.error('Failed to load image:', picture.name);
        if (loadingMsg.parentElement) {
            loadingMsg.remove();
        }
        alert('Failed to load image. Please refresh the page.');
    };
    // #region agent log
    fetch('http://127.0.0.1:7242/ingest/3400234f-86bf-4b16-8be0-11dc36af9821',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'script.js:1050',message:'Setting img.src in selectPicture',data:{imageName:picture.name,urlStart:picture.url.substring(0,50),isDataUrl:picture.url.startsWith('data:')},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'A'})}).catch(()=>{});
    // #endregion
    img.src = picture.url; // This should be a data URL, won't taint canvas
    
    // Close gallery
    galleryModal.classList.add('hidden');
}

// Gallery modal controls
galleryBtn.addEventListener('click', () => {
    galleryModal.classList.remove('hidden');
});

closeGallery.addEventListener('click', () => {
    galleryModal.classList.add('hidden');
});

galleryModal.addEventListener('click', (e) => {
    if (e.target === galleryModal) {
        galleryModal.classList.add('hidden');
    }
});

